{
  "nl": {
    "issue": [
      {
        "text": "仓储合同的定义，以及保管人接收、验收、接受检查、危险通知等主要义务",
        "rules": ["c904-def", "c907-1", "c911", "c912"]
      },
      {
        "text": "储存危险物品、易变质物品时存货人的说明义务，以及违反该义务时保管人的拒收权、处置权与费用负担",
        "rules": ["c906-1", "c906-2a", "c906-2b", "c906-2c", "c906-3"]
      },
      {
        "text": "入库仓储物的验收、验收时发现不符合约定的通知义务，以及验收后发生品种、数量、质量不符合约定时的赔偿责任",
        "rules": ["c907-1", "c907-2", "c907-3"]
      },
      {
        "text": "仓储物变质、损坏时的通知义务，危及其他仓储物时的催告处置权与紧急处置权",
        "rules": ["c912", "c913-1", "c913-2", "c913-3"]
      },
      {
        "text": "储存期限没有约定、约定不明确或者期限届满时，仓储物的提取、加收仓储费与提存",
        "rules": ["c914-1", "c914-2", "c914-3", "c915-1", "c915-2", "c915-3", "c916-1", "c916-2"]
      },
      {
        "text": "储存期内因保管不善造成仓储物毁损、灭失的赔偿责任及其免责事由",
        "rules": ["c917-1", "c917-exception"]
      }
    ],
    "conditions": [
      {
        "text": "存在保管人储存存货人交付的仓储物、存货人支付仓储费的合同",
        "rules": ["c904-def"]
      },
      {
        "text": "储存易燃、易爆、有毒、有腐蚀性、有放射性等危险物品或者易变质物品",
        "rules": ["c906-1"]
      },
      {
        "text": "存货人违反说明物品性质、提供有关资料的义务",
        "rules": ["c906-2a", "c906-2b", "c906-2c"]
      },
      {
        "text": "保管人储存危险物品",
        "rules": ["c906-3"]
      },
      {
        "text": "保管人按约定验收；验收时发现入库仓储物与约定不符合；验收后发生品种、数量、质量不符合约定",
        "rules": ["c907-1", "c907-2", "c907-3"]
      },
      {
        "text": "存货人或者仓单持有人要求检查仓储物或者提取样品",
        "rules": ["c911"]
      },
      {
        "text": "保管人发现入库仓储物有变质或者其他损坏；该变质、损坏危及其他仓储物的安全和正常保管；情况紧急",
        "rules": ["c912", "c913-1", "c913-2", "c913-3"]
      },
      {
        "text": "当事人对储存期限没有约定或者约定不明确",
        "rules": ["c914-1", "c914-2", "c914-3"]
      },
      {
        "text": "储存期限届满；逾期提取；提前提取",
        "rules": ["c915-1", "c915-2", "c915-3"]
      },
      {
        "text": "储存期限届满不提取仓储物，经催告在合理期限内仍不提取",
        "rules": ["c916-1", "c916-2"]
      },
      {
        "text": "储存期内因保管不善造成仓储物毁损、灭失",
        "rules": ["c917-1"]
      }
    ],
    "exceptions": [
      {
        "text": "因仓储物本身的自然性质、包装不符合约定或者超过有效储存期造成仓储物变质、损坏的，保管人不承担赔偿责任",
        "rules": ["c917-exception"]
      },
      {
        "text": "储存期限不明确时保管人虽可随时请求提取，但应当给予必要的准备时间",
        "rules": ["c914-3"]
      }
    ],
    "effects": [
      {
        "text": "存货人应当说明危险物品、易变质物品的性质并提供有关资料；保管人储存危险物品应当具备相应的保管条件",
        "rules": ["c906-1", "c906-3"]
      },
      {
        "text": "存货人违反说明义务的，保管人可以拒收仓储物，也可以采取相应措施以避免损失的发生，由此产生的费用由存货人负担",
        "rules": ["c906-2a", "c906-2b", "c906-2c"]
      },
      {
        "text": "保管人应当按约定验收，发现入库仓储物与约定不符合的应当及时通知存货人；验收后发生品种、数量、质量不符合约定的，保管人应当承担赔偿责任",
        "rules": ["c907-1", "c907-2", "c907-3"]
      },
      {
        "text": "保管人应当同意存货人或者仓单持有人检查仓储物、提取样品",
        "rules": ["c911"]
      },
      {
        "text": "保管人应当及时通知存货人或者仓单持有人仓储物变质、损坏；危及其他仓储物时应当催告作出必要处置，情况紧急可自行处置并事后及时通知",
        "rules": ["c912", "c913-1", "c913-2", "c913-3"]
      },
      {
        "text": "储存期限没有约定或者约定不明确的，存货人或者仓单持有人可以随时提取，保管人也可以随时请求提取",
        "rules": ["c914-1", "c914-2"]
      },
      {
        "text": "储存期限届满，存货人或者仓单持有人应当凭仓单、入库单等提取仓储物；逾期提取的应当加收仓储费，提前提取的不减收仓储费",
        "rules": ["c915-1", "c915-2", "c915-3"]
      },
      {
        "text": "期限届满不提取的，保管人可以催告在合理期限内提取；逾期不提取的，保管人可以提存仓储物",
        "rules": ["c916-1", "c916-2"]
      },
      {
        "text": "储存期内因保管不善造成仓储物毁损、灭失的，保管人应当承担赔偿责任",
        "rules": ["c917-1"]
      }
    ],
    "priority": [
      {
        "text": "第917条第1款后段的免责事由（自然性质、包装不符合约定、超过有效储存期）优先于同款前段的保管不善赔偿责任",
        "rules": ["c917-exception", "c917-1"]
      }
    ],
    "distinguish": [
      {
        "text": "仓储合同与一般保管合同：仓储合同为双务、有偿、诺成合同，一般保管合同可为无偿、实践合同（笔记与LEGO卡片，法条未明文）",
        "rules": []
      },
      {
        "text": "第907条第3款针对验收后发生的品种、数量、质量不符合约定的赔偿责任；第917条针对储存期内保管不善致毁损、灭失的赔偿责任，事由不同",
        "rules": ["c907-3", "c917-1"]
      },
      {
        "text": "第906条第2款的拒收权、采取措施权针对存货人未说明危险物品性质；第913条的催告与处置权针对入库后仓储物变质、损坏危及其他仓储物",
        "rules": ["c906-2a", "c906-2b", "c913-1", "c913-2"]
      },
      {
        "text": "第915条凭仓单、入库单提取是期限届满时的义务；第914条的随时提取适用于期限没有约定或者约定不明确的情形",
        "rules": ["c915-1", "c914-1"]
      }
    ]
  },
